var rm=window.matchMedia('(prefers-reduced-motion: reduce)');
var valEl=root.querySelector('.dsh14-kpi-tile-value');
var pctEl=root.querySelector('.dsh14-kpi-tile-pct');
var delta=root.querySelector('.dsh14-kpi-tile-delta');
var line=root.querySelector('.dsh14-kpi-tile-line');
var area=root.querySelector('.dsh14-kpi-tile-area');
var dot=root.querySelector('.dsh14-kpi-tile-dot');
var btn=root.querySelector('.dsh14-kpi-tile-refresh');
var raf=0,cur=0;
function money(n){return '$'+(n/1000).toFixed(1)+'k';}
function countTo(to){
  cancelAnimationFrame(raf);
  if(rm.matches){cur=to;valEl.textContent=money(to);return;}
  var from=cur,t0=performance.now(),d=900;
  function step(t){var p=Math.min(1,(t-t0)/d),e=1-Math.pow(1-p,3);cur=from+(to-from)*e;valEl.textContent=money(cur);if(p<1)raf=requestAnimationFrame(step);else cur=to;}
  raf=requestAnimationFrame(step);
}
function draw(){
  var n=13,v=.32+Math.random()*.24,pts=[];
  for(var i=0;i<n;i++){v+=(Math.random()-.4)*.18;v=Math.max(.06,Math.min(.94,v));pts.push([+(i*(120/(n-1))).toFixed(1),+(41-v*34).toFixed(1)]);}
  var s=pts.map(function(p){return p[0]+','+p[1];}).join(' ');
  line.setAttribute('points',s);
  area.setAttribute('points',s+' 120,44 0,44');
  var last=pts[n-1];
  dot.setAttribute('cx',Math.min(117.5,last[0]));
  dot.setAttribute('cy',last[1]);
  line.classList.remove('dsh14-kpi-tile-draw');
  void line.getBoundingClientRect();
  line.classList.add('dsh14-kpi-tile-draw');
  return pts;
}
function refresh(){
  var pts=draw();
  var up=pts[pts.length-1][1]<pts[pts.length-5][1];
  delta.classList.toggle('dsh14-kpi-tile-down',!up);
  area.style.fill=up?'rgba(61,220,151,.13)':'rgba(255,122,138,.13)';
  dot.style.stroke=up?'#3DDC97':'#FF7A8A';
  line.style.stroke=up?'#3DDC97':'#FF7A8A';
  pctEl.textContent=(up?'':'-')+(Math.random()*13+1.3).toFixed(1)+'%';
  countTo(Math.round(92000+Math.random()*86000));
}
btn.addEventListener('click',function(){
  if(root.classList.contains('dsh14-kpi-tile-loading'))return;
  root.classList.add('dsh14-kpi-tile-loading');
  setTimeout(function(){root.classList.remove('dsh14-kpi-tile-loading');refresh();},680);
});
refresh();

