var DATA=[{k:'Status',v:'Active',n:1840},{k:'Plan',v:'Pro',n:612},{k:'Region',v:'EU-West',n:344},{k:'Owner',v:'You',n:97}];
var state=DATA.map(function(d,i){return{d:d,on:i<3};});
var list=root.querySelector('.dsh14-filter-chips-list');
var menu=root.querySelector('.dsh14-filter-chips-menu');
var addBtn=root.querySelector('.dsh14-filter-chips-add');
var clearBtn=root.querySelector('.dsh14-filter-chips-clear');
var count=root.querySelector('.dsh14-filter-chips-count');
function sync(){
  var on=state.filter(function(s){return s.on;});
  root.classList.toggle('dsh14-filter-chips-none',on.length===0);
  var n=on.length?Math.min.apply(null,on.map(function(s){return s.d.n;})):2481;
  count.textContent=n.toLocaleString()+' rows';
  clearBtn.disabled=on.length===0;
  addBtn.disabled=on.length===state.length;
  if(addBtn.disabled)closeMenu();
}
function chip(s){
  var el=document.createElement('span');
  el.className='dsh14-filter-chips-chip';el.setAttribute('role','listitem');
  var t=document.createElement('span');
  t.innerHTML='';
  var k=document.createElement('span');k.className='dsh14-filter-chips-k';k.textContent=s.d.k+': ';
  var v=document.createElement('span');v.textContent=s.d.v;
  var x=document.createElement('button');x.type='button';x.className='dsh14-filter-chips-x';x.innerHTML='&times;';
  x.setAttribute('aria-label','Remove filter '+s.d.k+' '+s.d.v);
  x.addEventListener('click',function(){remove(s,el);});
  el.appendChild(k);el.appendChild(v);el.appendChild(x);
  return el;
}
function remove(s,el){
  if(!s.on)return;s.on=false;
  el.style.width=el.offsetWidth+'px';
  void el.offsetWidth;
  el.classList.add('dsh14-filter-chips-out');
  el.addEventListener('transitionend',function h(e){if(e.propertyName!=='width')return;el.removeEventListener('transitionend',h);if(el.parentNode)el.parentNode.removeChild(el);},false);
  setTimeout(function(){if(el.parentNode)el.parentNode.removeChild(el);},420);
  sync();
}
function addChip(s){s.on=true;list.appendChild(chip(s));sync();}
function closeMenu(){menu.hidden=true;addBtn.setAttribute('aria-expanded','false');menu.textContent='';}
addBtn.addEventListener('click',function(){
  if(!menu.hidden){closeMenu();return;}
  menu.textContent='';
  state.filter(function(s){return !s.on;}).forEach(function(s){
    var b=document.createElement('button');b.type='button';b.className='dsh14-filter-chips-opt';b.setAttribute('role','menuitem');
    b.textContent=s.d.k+': '+s.d.v;
    b.addEventListener('click',function(){addChip(s);closeMenu();addBtn.focus();});
    menu.appendChild(b);
  });
  menu.hidden=false;addBtn.setAttribute('aria-expanded','true');
  var f=menu.querySelector('.dsh14-filter-chips-opt');if(f)f.focus();
});
menu.addEventListener('keydown',function(e){if(e.key==='Escape'){closeMenu();addBtn.focus();}});
clearBtn.addEventListener('click',function(){
  Array.prototype.slice.call(list.children).forEach(function(el,i){
    setTimeout(function(){var s=state.filter(function(x){return x.on;})[0];if(s)remove(s,el);},i*55);
  });
});
state.forEach(function(s){if(s.on)list.appendChild(chip(s));});
sync();

