var M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var today=new Date();today.setHours(0,0,0,0);
var view=new Date(today.getFullYear(),today.getMonth(),1);
var start=new Date(today);start.setDate(start.getDate()-6);
var end=new Date(today);
var pending=false;
var grid=root.querySelector('.dsh14-daterange-grid');
var lab=root.querySelector('.dsh14-daterange-month');
var out=root.querySelector('.dsh14-daterange-out');
function key(d){return d.getFullYear()*10000+d.getMonth()*100+d.getDate();}
function fmt(d){return d?M[d.getMonth()]+' '+d.getDate():'…';}
function render(){
  lab.textContent=M[view.getMonth()]+' '+view.getFullYear();
  out.textContent=fmt(start)+' – '+fmt(end)+(end?', '+end.getFullYear():'');
  grid.textContent='';
  var y=view.getFullYear(),m=view.getMonth();
  var pad=new Date(y,m,1).getDay();
  var days=new Date(y,m+1,0).getDate();
  for(var i=0;i<pad;i++){var s=document.createElement('span');s.className='dsh14-daterange-pad';grid.appendChild(s);}
  for(var d=1;d<=days;d++){
    var dt=new Date(y,m,d),k=key(dt);
    var b=document.createElement('button');
    b.type='button';b.className='dsh14-daterange-day';b.textContent=d;b.__d=dt;
    b.setAttribute('aria-label',M[m]+' '+d+', '+y);
    if(start&&end&&k>key(start)&&k<key(end))b.className+=' dsh14-daterange-in';
    if(start&&k===key(start))b.className+=' dsh14-daterange-s';
    if(end&&k===key(end))b.className+=' dsh14-daterange-e';
    if(k===key(today)){b.className+=' dsh14-daterange-today';b.setAttribute('aria-current','date');}
    b.setAttribute('aria-pressed',(start&&end&&k>=key(start)&&k<=key(end))?'true':'false');
    grid.appendChild(b);
  }
}
function clearPills(){root.querySelectorAll('.dsh14-daterange-pill').forEach(function(p){p.setAttribute('aria-pressed','false');});}
grid.addEventListener('click',function(e){
  var b=e.target.closest('.dsh14-daterange-day');if(!b||!grid.contains(b))return;
  if(!pending){start=b.__d;end=null;pending=true;}
  else{if(key(b.__d)<key(start)){end=start;start=b.__d;}else{end=b.__d;}pending=false;}
  clearPills();render();
});
grid.addEventListener('keydown',function(e){
  var b=e.target.closest('.dsh14-daterange-day');if(!b)return;
  var step={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];
  if(!step)return;e.preventDefault();
  var all=Array.prototype.slice.call(grid.querySelectorAll('.dsh14-daterange-day'));
  var i=all.indexOf(b)+step;
  if(i>=0&&i<all.length)all[i].focus();
});
root.querySelectorAll('.dsh14-daterange-nav').forEach(function(n){
  n.addEventListener('click',function(){view=new Date(view.getFullYear(),view.getMonth()+ +n.getAttribute('data-d'),1);render();});
});
root.querySelectorAll('.dsh14-daterange-pill').forEach(function(p){
  p.addEventListener('click',function(){
    var v=p.getAttribute('data-p');
    end=new Date(today);
    if(v==='mtd'){start=new Date(today.getFullYear(),today.getMonth(),1);}
    else{start=new Date(today);start.setDate(start.getDate()-(+v-1));}
    pending=false;view=new Date(end.getFullYear(),end.getMonth(),1);
    clearPills();p.setAttribute('aria-pressed','true');render();
  });
});
