js:
var DATA=[
 {t:'Checkout p95 above 800 ms',m:'Alerting · 4 min ago',u:true},
 {t:'Amara requested your review',m:'#4182 Rate limiter · 22 min ago',u:true},
 {t:'Invoice 2214 was paid',m:'Billing · 1 hr ago',u:true},
 {t:'Weekly usage digest ready',m:'Reports · Yesterday',u:false},
 {t:'2 seats added to workspace',m:'Admin · Monday',u:false}
];
var list=root.querySelector('.dsh14-notif-center-list');
var badge=root.querySelector('.dsh14-notif-center-badge');
var bell=root.querySelector('.dsh14-notif-center-bell');
var allBtn=root.querySelector('.dsh14-notif-center-all');
var unreadOnly=false;
function count(){return DATA.filter(function(d){return d.u;}).length;}
function sync(){
  var c=count();
  badge.textContent=c;
  root.classList.toggle('dsh14-notif-center-zero',c===0);
  allBtn.disabled=c===0;
  badge.classList.add('dsh14-notif-center-bump');
  setTimeout(function(){badge.classList.remove('dsh14-notif-center-bump');},220);
  var shown=0;
  Array.prototype.forEach.call(list.children,function(li,i){
    var hide=unreadOnly&&!DATA[i].u;
    li.classList.toggle('dsh14-notif-center-hide',hide);
    if(!hide)shown++;
  });
  root.classList.toggle('dsh14-notif-center-showempty',shown===0);
}
DATA.forEach(function(d,i){
  var li=document.createElement('li');
  var b=document.createElement('button');
  b.type='button';
  b.className='dsh14-notif-center-item'+(d.u?'':' dsh14-notif-center-read');
  b.setAttribute('aria-label',(d.u?'Unread: ':'')+d.t);
  var t=document.createElement('span');t.className='dsh14-notif-center-t';t.textContent=d.t;
  var m=document.createElement('span');m.className='dsh14-notif-center-m';m.textContent=d.m;
  b.appendChild(t);b.appendChild(m);
  b.addEventListener('click',function(){
    if(!d.u)return;
    d.u=false;b.classList.add('dsh14-notif-center-read');b.setAttribute('aria-label',d.t);
    sync();
  });
  li.appendChild(b);
  li.className='dsh14-notif-center-li';
  list.appendChild(li);
});
bell.addEventListener('click',function(){
  unreadOnly=!unreadOnly;
  bell.setAttribute('aria-pressed',unreadOnly?'true':'false');
  root.classList.remove('dsh14-notif-center-ring');
  void root.offsetWidth;
  root.classList.add('dsh14-notif-center-ring');
  sync();
});
allBtn.addEventListener('click',function(){
  DATA.forEach(function(d,i){
    if(!d.u)return;
    setTimeout(function(){
      d.u=false;
      list.children[i].firstChild.classList.add('dsh14-notif-center-read');
      sync();
    },i*90);
  });
});
sync();

