js:
var GROUPS=[
 {g:'People',c:'g0',rows:[{n:'Amara Osei',s:'Design'},{n:'Tobias Lund',s:'Platform'},{n:'Priya Raman',s:'Growth'}]},
 {g:'Projects',c:'g1',rows:[{n:'Payments migration',s:'On track'},{n:'Pricing experiment',s:'At risk'}]},
 {g:'Documents',c:'g2',rows:[{n:'Q3 roadmap',s:'Doc'},{n:'Incident 214 postmortem',s:'Doc'}]}
];
var input=root.querySelector('.dsh14-search-groups-input');
var out=root.querySelector('.dsh14-search-groups-out');
function mark(text,q){
  var frag=document.createDocumentFragment();
  var i=q?text.toLowerCase().indexOf(q.toLowerCase()):-1;
  if(i<0){frag.appendChild(document.createTextNode(text));return frag;}
  frag.appendChild(document.createTextNode(text.slice(0,i)));
  var m=document.createElement('span');m.className='dsh14-search-groups-hit';m.textContent=text.slice(i,i+q.length);
  frag.appendChild(m);
  frag.appendChild(document.createTextNode(text.slice(i+q.length)));
  return frag;
}
function render(q){
  out.textContent='';
  var n=0,d=0;
  GROUPS.forEach(function(gr){
    var rows=gr.rows.filter(function(r){return !q||(r.n+' '+r.s).toLowerCase().indexOf(q.toLowerCase())>=0;});
    if(!rows.length)return;
    var h=document.createElement('div');h.className='dsh14-search-groups-gh';h.textContent=gr.g;
    out.appendChild(h);
    rows.forEach(function(r){
      var b=document.createElement('button');
      b.type='button';b.setAttribute('role','option');b.setAttribute('aria-selected','false');b.tabIndex=-1;
      b.className='dsh14-search-groups-opt dsh14-search-groups-'+gr.c;
      b.style.animationDelay=(d++*28)+'ms';
      var av=document.createElement('span');av.className='dsh14-search-groups-av';av.textContent=r.n.charAt(0);
      var nm=document.createElement('span');nm.className='dsh14-search-groups-nm';nm.appendChild(mark(r.n,q));
      var sb=document.createElement('span');sb.className='dsh14-search-groups-sub';sb.textContent=r.s;
      b.appendChild(av);b.appendChild(nm);b.appendChild(sb);
      b.addEventListener('click',function(){
        out.querySelectorAll('.dsh14-search-groups-opt').forEach(function(o){o.setAttribute('aria-selected','false');});
        b.setAttribute('aria-selected','true');
        input.value=r.n;render(r.n);input.focus();
      });
      out.appendChild(b);n++;
    });
  });
  if(!n){
    var e=document.createElement('div');e.className='dsh14-search-groups-none';
    var t=document.createElement('b');t.textContent='No matches';
    e.appendChild(t);
    e.appendChild(document.createTextNode('Nothing for "'+q+'" — try a person or project.'));
    out.appendChild(e);
  }
}
function opts(){return Array.prototype.slice.call(out.querySelectorAll('.dsh14-search-groups-opt'));}
input.addEventListener('input',function(){render(input.value.trim());});
input.addEventListener('keydown',function(e){
  if(e.key==='ArrowDown'){var o=opts();if(o.length){e.preventDefault();o[0].focus();}}
});
out.addEventListener('keydown',function(e){
  var b=e.target.closest('.dsh14-search-groups-opt');if(!b)return;
  var o=opts(),i=o.indexOf(b);
  if(e.key==='ArrowDown'){e.preventDefault();if(i<o.length-1)o[i+1].focus();}
  else if(e.key==='ArrowUp'){e.preventDefault();if(i>0)o[i-1].focus();else input.focus();}
  else if(e.key==='Escape'){e.preventDefault();input.focus();}
});
render('');

