.dsh14-settings-panel-in{overflow:hidden;min-height:0;padding:0 2px}
.dsh14-settings-panel-row{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:4px 0 8px}
.dsh14-settings-panel-lb{font-size:11px;color:#B4BDD2}
.dsh14-settings-panel-sw{position:relative;flex:none;width:32px;height:18px;border-radius:99px;border:1px solid var(--p-ln);background:rgba(255,255,255,.06);cursor:pointer;padding:0;transition:background .24s,border-color .24s}
.dsh14-settings-panel-sw[aria-checked="true"]{background:rgba(124,155,255,.85);border-color:rgba(124,155,255,.9)}
.dsh14-settings-panel-sw:focus-visible{outline:2px solid var(--p-ac);outline-offset:2px}
.dsh14-settings-panel-knob{position:absolute;top:2px;left:2px;width:12px;height:12px;border-radius:50%;background:#8E98AE;transition:transform .34s cubic-bezier(.3,1.6,.4,1),background .24s,width .2s}
.dsh14-settings-panel-sw[aria-checked="true"] .dsh14-settings-panel-knob{transform:translateX(14px);background:#0C0F17}
.dsh14-settings-panel-sw:active .dsh14-settings-panel-knob{width:16px}
.dsh14-settings-panel-seg{display:flex;gap:3px;padding:4px 0 9px}
.dsh14-settings-panel-sg{flex:1;border:1px solid var(--p-ln);border-radius:7px;background:transparent;color:var(--p-dm);font-family:inherit;font-size:10px;font-weight:650;padding:4px 0;cursor:pointer;transition:color .18s,background .18s,border-color .18s,transform .2s cubic-bezier(.2,1.6,.4,1)}
.dsh14-settings-panel-sg:hover{color:var(--p-tx)}
.dsh14-settings-panel-sg:active{transform:scale(.94)}
.dsh14-settings-panel-sg[aria-pressed="true"]{color:#DCE4FF;background:rgba(124,155,255,.16);border-color:rgba(124,155,255,.45)}
.dsh14-settings-panel-sg:focus-visible{outline:2px solid var(--p-ac);outline-offset:2px}
.dsh14-settings-panel-bar{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 11px;background:rgba(19,23,33,.96);border-top:1px solid var(--p-ln);transform:translateY(110%);transition:transform .34s cubic-bezier(.3,1.2,.35,1)}
.dsh14-settings-panel-dirty .dsh14-settings-panel-bar,.dsh14-settings-panel-saved .dsh14-settings-panel-bar{transform:none}
.dsh14-settings-panel-msg{font-size:10px;color:#FFB454;font-weight:650}
.dsh14-settings-panel-saved .dsh14-settings-panel-msg{color:#3DDC97}
.dsh14-settings-panel-save{border:0;border-radius:7px;background:var(--p-ac);color:#0B0E16;font-family:inherit;font-size:10px;font-weight:800;padding:4px 11px;cursor:pointer;transition:filter .16s,transform .2s cubic-bezier(.2,1.6,.4,1),opacity .2s}
.dsh14-settings-panel-save:hover{filter:brightness(1.1)}
.dsh14-settings-panel-save:active{transform:scale(.94)}
.dsh14-settings-panel-save:focus-visible{outline:2px solid #fff;outline-offset:2px}
.dsh14-settings-panel-saved .dsh14-settings-panel-save{opacity:0;pointer-events:none}
@media (prefers-reduced-motion:reduce){.dsh14-settings-panel *{animation-duration:.01ms!important;transition-duration:.01ms!important}}

js:
var msg=root.querySelector('.dsh14-settings-panel-msg');
var save=root.querySelector('.dsh14-settings-panel-save');
var timer=0;
function dirty(){
  clearTimeout(timer);
  root.classList.remove('dsh14-settings-panel-saved');
  root.classList.add('dsh14-settings-panel-dirty');
  msg.textContent='Unsaved changes';
}
root.querySelectorAll('.dsh14-settings-panel-sh').forEach(function(h){
  h.addEventListener('click',function(){
    var sec=h.parentNode;
    var open=sec.classList.toggle('dsh14-settings-panel-open');
    h.setAttribute('aria-expanded',open?'true':'false');
  });
});
root.querySelectorAll('.dsh14-settings-panel-sw').forEach(function(sw){
  sw.addEventListener('click',function(){
    sw.setAttribute('aria-checked',sw.getAttribute('aria-checked')==='true'?'false':'true');
    dirty();
  });
});
var segs=root.querySelectorAll('.dsh14-settings-panel-sg');
segs.forEach(function(s){
  s.addEventListener('click',function(){
    if(s.getAttribute('aria-pressed')==='true')return;
    segs.forEach(function(o){o.setAttribute('aria-pressed','false');});
    s.setAttribute('aria-pressed','true');
    dirty();
  });
});
save.addEventListener('click',function(){
  msg.textContent='Saving…';
  setTimeout(function(){
    root.classList.remove('dsh14-settings-panel-dirty');
    root.classList.add('dsh14-settings-panel-saved');
    msg.textContent='✓ Preferences saved';
    timer=setTimeout(function(){root.classList.remove('dsh14-settings-panel-saved');},1600);
  },520);
});

css:
.dsh14-kanban-col{--b-tx:#E9ECF5;--b-dm:#7E88A0;--b-ln:rgba(255,255,255,.09);--b-ac:#7C9BFF;box-sizing:border-box;width:100%;max-width:300px;padding:9px 10px;border:1px solid var(--b-ln);border-radius:14px;background:#12151E;color:var(--b-tx);font-family:ui-sans-serif,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;touch-action:pan-y}
.dsh14-kanban-col *{box-sizing:border-box}
.dsh14-kanban-col-head{display:flex;align-items:center;gap:6px;margin-bottom:7px}
.dsh14-kanban-col-dot{width:6px;height:6px;border-radius:2px;background:#FFB454}
.dsh14-kanban-col-name{font-size:10px;font-weight:750;letter-spacing:.07em;text-transform:uppercase;color:#C5CCDC}
.dsh14-kanban-col-wip{margin-left:auto;font-size:9px;font-weight:700;color:var(--b-dm);background:rgba(255,255,255,.05);border:1px solid var(--b-ln);border-radius:5px;padding:1px 5px;font-variant-numeric:tabular-nums;transition:color .2s,border-color .2s}
.dsh14-kanban-col-full .dsh14-kanban-col-wip{color:#FF7A8A;border-color:rgba(255,122,138,.4)}
.dsh14-kanban-col-list{position:relative;list-style:none;margin:0 0 6px;padding:0;display:flex;flex-direction:column;gap:5px;max-height:92px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.18) transparent}
.dsh14-kanban-col-list::-webkit-scrollbar{width:4px}
.dsh14-kanban-col-list::-webkit-scrollbar-thumb{background:rgba(255,255,255,.16);border-radius:4px}
.dsh14-kanban-col-card{display:flex;align-items:center;gap:7px;padding:6px 7px;border:1px solid var(--b-ln);border-radius:9px;background:#181D2A;cursor:grab;user-select:none;transition:transform .22s cubic-bezier(.3,1,.3,1),box-shadow .2s,border-color .2s,opacity .2s;animation:dsh14-kanban-col-in .3s cubic-bezier(.2,1.4,.4,1) both}
@keyframes dsh14-kanban-col-in{from{opacity:0;transform:translateY(-6px) scale(.96)}to{opacity:1;transform:none}}
.dsh14-kanban-col-card:hover{border-color:rgba(255,255,255,.2)}
.dsh14-kanban-col-card:focus-visible{outline:2px solid var(--b-ac);outline-offset:1px}
.dsh14-kanban-col-drag{cursor:grabbing;z-index:3;box-shadow:0 12px 22px rgba(0,0,0,.55);border-color:rgba(124,155,255,.6);transition:none}
.dsh14-kanban-col-grabbed{border-color:rgba(124,155,255,.75);box-shadow:0 0 0 3px rgba(124,155,255,.2)}
.dsh14-kanban-col-grip{flex:none;display:grid;grid-template-columns:2px 2px;gap:2px;padding:0;width:8px;border:0;background:transparent;cursor:grab}
.dsh14-kanban-col-grip i{width:2px;height:2px;border-radius:50%;background:#5E677D;transition:background .18s}
.dsh14-kanban-col-card:hover .dsh14-kanban-col-grip i{background:#98A2B8}
.dsh14-kanban-col-grip:focus-visible{outline:2px solid var(--b-ac);outline-offset:3px;border-radius:3px}
.dsh14-kanban-col-t{flex:1;min-width:0;font-size:11px;color:#D5DBE8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dsh14-kanban-col-tag{flex:none;font-size:8.5px;font-weight:800;letter-spacing:.04em;padding:1px 5px;border-radius:4px;background:rgba(124,155,255,.16);color:#AFC0FF}
.dsh14-kanban-col-hi .dsh14-kanban-col-tag{background:rgba(255,122,138,.16);color:#FFAFB8}
.dsh14-kanban-col-lo .dsh14-kanban-col-tag{background:rgba(61,220,151,.14);color:#8BE9C4}
.dsh14-kanban-col-add{margin:0}
.dsh14-kanban-col-input{width:100%;border:1px dashed rgba(255,255,255,.16);border-radius:8px;background:transparent;color:var(--b-tx);font-family:inherit;font-size:10.5px;padding:5px 7px;outline:none;transition:border-color .2s,background .2s}
.dsh14-kanban-col-input::placeholder{color:#5E677D}
