js:
var list=root.querySelector('.dsh14-kanban-col-list');
var wip=root.querySelector('.dsh14-kanban-col-wip');
var form=root.querySelector('.dsh14-kanban-col-add');
var input=root.querySelector('.dsh14-kanban-col-input');
var LIMIT=5,drag=null,grabbed=null;
function card(t,tag,cls){
  var li=document.createElement('li');
  li.className='dsh14-kanban-col-card'+(cls?' dsh14-kanban-col-'+cls:'');
  li.tabIndex=0;
  li.setAttribute('aria-roledescription','Draggable card');
  var g=document.createElement('button');
  g.type='button';g.className='dsh14-kanban-col-grip';
  g.setAttribute('aria-label','Reorder '+t+'. Press space to grab, then arrow keys.');
  for(var i=0;i<4;i++)g.appendChild(document.createElement('i'));
  var s=document.createElement('span');s.className='dsh14-kanban-col-t';s.textContent=t;
  var b=document.createElement('span');b.className='dsh14-kanban-col-tag';b.textContent=tag;
  li.appendChild(g);li.appendChild(s);li.appendChild(b);
  return li;
}
function sync(){
  var n=list.children.length;
  wip.textContent=n+' / '+LIMIT;
  root.classList.toggle('dsh14-kanban-col-full',n>=LIMIT);
  input.disabled=n>=LIMIT;
  input.placeholder=n>=LIMIT?'WIP limit reached':'＋ Add a card…';
}
[['Retry budget for webhooks','ENG','hi'],['Pricing page copy pass','DES',''],['Seat billing migration','OPS','lo']].forEach(function(a){list.appendChild(card(a[0],a[1],a[2]));});
sync();
list.addEventListener('pointerdown',function(e){
  if(e.button!==0)return;
  var c=e.target.closest('.dsh14-kanban-col-card');
  if(!c||!list.contains(c))return;
  var items=Array.prototype.slice.call(list.children);
  drag={c:c,items:items,from:items.indexOf(c),to:items.indexOf(c),y:e.clientY,h:c.offsetHeight+5};
  c.setPointerCapture(e.pointerId);
  c.classList.add('dsh14-kanban-col-drag');
});
list.addEventListener('pointermove',function(e){
  if(!drag)return;
  var dy=e.clientY-drag.y;
  drag.c.style.transform='translateY('+dy+'px) scale(1.03)';
  var to=Math.max(0,Math.min(drag.items.length-1,drag.from+Math.round(dy/drag.h)));
  if(to!==drag.to){
    drag.to=to;
    drag.items.forEach(function(it,i){
      if(it===drag.c)return;
      var s=0;
      if(to>drag.from&&i>drag.from&&i<=to)s=-drag.h;
      if(to<drag.from&&i>=to&&i<drag.from)s=drag.h;
      it.style.transform=s?'translateY('+s+'px)':'';
    });
  }
});
function endDrag(){
  if(!drag)return;
  var d=drag;drag=null;
  d.items.forEach(function(it){it.style.transform='';});
  d.c.classList.remove('dsh14-kanban-col-drag');
  if(d.to!==d.from){
    var ref=d.items[d.to];
    if(d.to>d.from)list.insertBefore(d.c,ref.nextSibling);else list.insertBefore(d.c,ref);
  }
}
list.addEventListener('pointerup',endDrag);
list.addEventListener('pointercancel',endDrag);
list.addEventListener('keydown',function(e){
  var c=e.target.closest('.dsh14-kanban-col-card');
  if(!c)return;
  if(e.key===' '||e.key==='Enter'){
    if(e.target.className.indexOf('dsh14-kanban-col-grip')<0&&e.key==='Enter')return;
    e.preventDefault();
    if(grabbed===c){grabbed=null;c.classList.remove('dsh14-kanban-col-grabbed');}
    else{if(grabbed)grabbed.classList.remove('dsh14-kanban-col-grabbed');grabbed=c;c.classList.add('dsh14-kanban-col-grabbed');}
    return;
  }
  if(e.key!=='ArrowUp'&&e.key!=='ArrowDown')return;
  e.preventDefault();
  var up=e.key==='ArrowUp';
  if(grabbed===c){
    var sib=up?c.previousElementSibling:c.nextElementSibling;
    if(!sib)return;
    if(up)list.insertBefore(c,sib);else list.insertBefore(sib,c);
    e.target.focus();
  }else{
    var nx=up?c.previousElementSibling:c.nextElementSibling;
    if(nx)nx.focus();
  }
});
form.addEventListener('submit',function(e){
  e.preventDefault();
  var v=input.value.trim();
  if(!v||list.children.length>=LIMIT)return;
  list.appendChild(card(v,'NEW','lo'));
  input.value='';sync();
  list.scrollTop=list.scrollHeight;
});
